static List<String> rrf(List<List<String>> rankings, int k) {
    Map<String, Double> scores = new HashMap<>();
    for (List<String> ranking : rankings) {
        for (int i = 0; i < ranking.size(); i++) {
            scores.merge(ranking.get(i), 1.0 / (k + i + 1), Double::sum);
        }
    }
    return scores.entrySet().stream()
        .sorted(Map.Entry.<String, Double>comparingByValue().reversed())
        .map(Map.Entry::getKey)
        .toList();
}

static double recallAtK(List<String> retrieved, Set<String> relevant, int k) {
    long hits = retrieved.subList(0, Math.min(k, retrieved.size())).stream()
        .filter(relevant::contains).distinct().count();
    return (double) hits / relevant.size();
}

static double mrr(List<List<String>> retrieved, List<Set<String>> relevant) {
    double total = 0.0;
    for (int q = 0; q < retrieved.size(); q++) {
        List<String> docs = retrieved.get(q);
        for (int i = 0; i < docs.size(); i++) {
            if (relevant.get(q).contains(docs.get(i))) {
                total += 1.0 / (i + 1);
                break;
            }
        }
    }
    return total / retrieved.size();
}

static double ndcgAtK(double[] rels, int k) {
    double[] ideal = rels.clone();
    Arrays.sort(ideal);
    for (int i = 0; i < ideal.length / 2; i++) {
        double t = ideal[i];
        ideal[i] = ideal[ideal.length - 1 - i];
        ideal[ideal.length - 1 - i] = t;
    }
    double idcg = dcg(ideal, k);
    return idcg == 0 ? 0.0 : dcg(rels, k) / idcg;
}

static double dcg(double[] r, int k) {
    double sum = 0.0;
    for (int i = 0; i < Math.min(k, r.length); i++) {
        sum += r[i] / (Math.log(i + 2) / Math.log(2));
    }
    return sum;
}

static double cosine(double[] a, double[] b) {
    double dot = 0, na = 0, nb = 0;
    for (int i = 0; i < a.length; i++) {
        dot += a[i] * b[i];
        na += a[i] * a[i];
        nb += b[i] * b[i];
    }
    return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

